// ── TITLE SEQUENCE BEFORE THE START SCREEN (v354, Silvio 25.11.2026) ──
// "Developed for" and the Hard Light Productions banner fade in, fade out,
// then the Series Resurrecta lockup with a band of light travelling across
// logo and lettering. The nebula, stars and planets of the start screen are
// already on the canvas when this runs, so the sequence plays over the same
// sky. The ship models load behind it: f3dLoadBoxShow keeps the loading bar
// out of sight until the sequence is through. A click or any key skips it.
//
// The two pictures ride in the source as base64 like the explosion sheets in
// 63_fxanim.js. They are nobody's sprite and come from no model, so there is
// no folder on the server for them.
const INTRO_B64 = {
  hlp: '',
  sr:  ''
};
// Milliseconds from the first frame of the sequence. Fades are given as
// [in starts, in ends, out starts, out ends].
const INTRO_T = {
  kicker: [450, 1450, 4300, 5200],
  banner: [1600, 2800, 4300, 5200],
  sr:     [5400, 6600, 10200, 11300],
  sweepAt: 5500,      // the light starts with the lockup, not before it
  sweepEvery: 1600,   // one pass, then a short wait
  sweepPass: 0.62,    // share of that time the light is moving
  end: 11400
};
const INTRO = {armed: true, done: false, t0: 0, wait: 0, img: {}, cv: {}};

function introOn(){ return INTRO.armed && !INTRO.done; }
function introSkip(){ INTRO.done = true; }

// The pictures are decoded once, on the first frame that wants them.
function introLoad(){
  if(INTRO.img.hlp || typeof Image === 'undefined') return;
  for(const k of ['hlp', 'sr']){
    const im = new Image();
    im.src = 'data:image/webp;base64,' + INTRO_B64[k];
    INTRO.img[k] = im;
  }
}
function introReady(){
  const a = INTRO.img.hlp, b = INTRO.img.sr;
  return !!(a && b && a.complete && b.complete && a.naturalWidth && b.naturalWidth);
}
// 0 before the fade in, 1 while it stands, 0 after the fade out.
function introFade(t, s){
  if(t <= s[0] || t >= s[3]) return 0;
  if(t < s[1]) return (t - s[0])/(s[1] - s[0]);
  if(t <= s[2]) return 1;
  return 1 - (t - s[2])/(s[3] - s[2]);
}
// Canvas has no letter spacing, so the characters are set one at a time -
// the same way the title sets FREESPACE.
function introTracked(text, size, track, cx, y, col, glow, alpha){
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.font = thLabel(size);
  ctx.textBaseline = 'middle'; ctx.textAlign = 'left';
  let w = 0;
  for(const ch of text) w += ctx.measureText(ch).width + track;
  w -= track;
  let x = cx - w/2;
  if(glow){ ctx.shadowColor = glow; ctx.shadowBlur = 18; }
  ctx.fillStyle = col;
  for(const ch of text){ ctx.fillText(ch, x, y); x += ctx.measureText(ch).width + track; }
  ctx.restore();
}
function introCv(k, w, h){
  let c = INTRO.cv[k];
  if(!c) c = INTRO.cv[k] = document.createElement('canvas');
  if(c.width !== w || c.height !== h){ c.width = w; c.height = h; }
  return c;
}
// The travelling light: a soft band, clipped to the lockup's own shape and
// added on top, so only logo and lettering light up and never the black
// around them. Same idea as the screen blend of the design.
function introSweep(t, dx, dy, dw, dh, alpha){
  if(t < INTRO_T.sweepAt) return;
  const ph = ((t - INTRO_T.sweepAt) % INTRO_T.sweepEvery)/INTRO_T.sweepEvery;
  if(ph > INTRO_T.sweepPass) return;                 // the wait between passes
  const p = ph/INTRO_T.sweepPass;
  const iw = Math.max(2, Math.round(dw)), ih = Math.max(2, Math.round(dh));
  const c = introCv('sweep', iw, ih), bx = c.getContext('2d');
  bx.setTransform(1, 0, 0, 1, 0, 0);
  bx.clearRect(0, 0, iw, ih);
  const band = iw*0.13;
  const cx = -band + p*(iw + 2*band);
  bx.save();
  bx.translate(cx, ih/2); bx.rotate(-14*Math.PI/180); bx.translate(-cx, -ih/2);
  const g = bx.createLinearGradient(cx - band/2, 0, cx + band/2, 0);
  g.addColorStop(0.00, 'rgba(255,176,118,0)');
  g.addColorStop(0.26, 'rgba(255,176,118,0.62)');
  g.addColorStop(0.50, 'rgba(255,246,236,1)');
  g.addColorStop(0.74, 'rgba(255,176,118,0.62)');
  g.addColorStop(1.00, 'rgba(255,176,118,0)');
  bx.fillStyle = g;
  bx.fillRect(cx - band/2, -ih, band, ih*3);
  bx.restore();
  bx.globalCompositeOperation = 'destination-in';
  bx.drawImage(INTRO.img.sr, 0, 0, iw, ih);
  bx.globalCompositeOperation = 'source-over';
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = alpha;
  ctx.drawImage(c, dx, dy, dw, dh);
  ctx.restore();
}
// strength: how much red glow is laid around the picture. The banner brings
// its own glow with it and needs only a little; the lockup is flat artwork
// and carries the whole of it (Silvio: there it may be strong).
function introDrawImg(im, dx, dy, dw, dh, alpha, glow, blur, strength){
  ctx.save();
  if(glow && strength > 0){
    ctx.shadowColor = glow; ctx.shadowBlur = blur;
    const passes = strength > 1 ? 2 : 1;
    ctx.globalAlpha = alpha*Math.min(1, strength);
    for(let i = 0; i < passes; i++) ctx.drawImage(im, dx, dy, dw, dh);
  }
  ctx.shadowBlur = 0;
  ctx.globalAlpha = alpha;
  ctx.drawImage(im, dx, dy, dw, dh);
  ctx.restore();
}
function drawIntro(){
  introLoad();
  // The models start loading right away; only the bar waits.
  if(typeof f3dPreloadBar === 'function') try{ f3dPreloadBar(); }catch(e){}
  // v354a (Silvio): the bar runs to its end first. The loading page puts it
  // up before the game even exists, so a sequence that started here would
  // push it aside and let it come back - the bar must finish, then this
  // starts. Both handles are cleared by f3dLoadBoxShow once the ships are on
  // the graphics card.
  if(typeof window !== 'undefined' && (window.FS3_LOADBOX || F3D_BOX)) return;
  const now = performance.now();
  if(!introReady()){
    // Give the two pictures a moment. If they will not come, skip the
    // sequence rather than hold the player on a black screen.
    if(!INTRO.wait) INTRO.wait = now;
    if(now - INTRO.wait > 4000) INTRO.done = true;
    return;
  }
  if(!INTRO.t0) INTRO.t0 = now;
  const t = now - INTRO.t0;

  // The same veil the start screen uses, so the sky reads the same way.
  const veil = ctx.createLinearGradient(0, 0, 0, H);
  veil.addColorStop(0.00, 'rgba(0,0,8,0.20)');
  veil.addColorStop(0.45, 'rgba(0,0,8,0.42)');
  veil.addColorStop(1.00, 'rgba(0,0,8,0.78)');
  ctx.fillStyle = veil; ctx.fillRect(0, 0, W, H);

  const RED = 'rgba(255,70,30,0.55)';

  // ── Developed for / Hard Light Productions ──
  const aK = introFade(t, INTRO_T.kicker), aB = introFade(t, INTRO_T.banner);
  if(aK > 0 || aB > 0){
    const bw = Math.min(640, W*0.55);
    const bh = bw*INTRO.img.hlp.naturalHeight/INTRO.img.hlp.naturalWidth;
    const gap = 26, kh = 20;
    const top = (H - (kh + gap + bh))/2;
    if(aK > 0) introTracked('DEVELOPED FOR', 15, 7, W/2, top + kh/2, '#e3d2cb', RED, aK);
    if(aB > 0) introDrawImg(INTRO.img.hlp, (W-bw)/2, top + kh + gap, bw, bh, aB, RED, 26, 0.45);
  }

  // ── Series Resurrecta ──
  const aS = introFade(t, INTRO_T.sr);
  if(aS > 0){
    const sw = Math.min(880, W*0.68);
    const sh = sw*INTRO.img.sr.naturalHeight/INTRO.img.sr.naturalWidth;
    const sx = (W-sw)/2, sy = (H-sh)/2;
    introDrawImg(INTRO.img.sr, sx, sy, sw, sh, aS, RED, 30, 1.6);
    introSweep(t, sx, sy, sw, sh, aS);
  }

  if(t >= INTRO_T.end) INTRO.done = true;
}
